import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        int current = 1, answer = 1;
        for (int i = 1; i < n; i++) {
            current = a[i - 1] <= a[i] ? current + 1 : 1; // a drop restarts the run
            answer = Math.max(answer, current);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	current, answer := 1, 1
	for i := 1; i < n; i++ {
		if a[i-1] <= a[i] {
			current++
		} else {
			current = 1 // a drop restarts the run
		}
		answer = max(answer, current)
	}
	fmt.Println(answer)
}
